#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <string>
#include <vector>

struct Job {
  std::string name;
  int priority;              // higher runs first
  std::int64_t deadline_ms;  // earlier runs first among equal priorities
};

// True when a must run strictly before b; false both ways for two jobs that tie.
[[nodiscard]] bool runs_before(const Job& a, const Job& b) {
  if (a.priority != b.priority) return a.priority > b.priority;
  return a.deadline_ms < b.deadline_ms;
}

int main() {
  std::vector<Job> jobs{
      {"dock", 1, 900}, {"estop-test", 3, 500}, {"map", 2, 700}, {"log", 1, 300}, {"calib", 2, 700}};
  std::ranges::stable_sort(jobs, runs_before);
  for (const Job& job : jobs) std::cout << job.name << ' ';
  std::cout << '\n';
}

