#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <vector>

struct Reading {
  int robot;
  std::int64_t stamp_ms;
};

// The time stamps of one robot, in the order they appear in the log.
[[nodiscard]] std::string stamps_of(std::span<const Reading> log, int robot) {
  std::string out;
  for (const Reading& r : log)
    if (r.robot == robot) out += std::format(" {}", r.stamp_ms);
  return out;
}

int main() {
  std::vector<Reading> log;  // in time order, three robots interleaved
  for (int i = 0; i < 24; ++i) log.push_back({.robot = i % 3, .stamp_ms = 10 * i});

  std::vector<Reading> a = log;
  std::ranges::sort(a, {}, &Reading::robot);
  std::vector<Reading> b = log;
  std::ranges::stable_sort(b, {}, &Reading::robot);

  std::cout << "robot 0 after sort:       " << stamps_of(a, 0) << '\n';
  std::cout << "robot 0 after stable_sort:" << stamps_of(b, 0) << '\n';
}

