// Textbook quicksort: the last element is the pivot (Lomuto's partition).
void quicksort(std::span<int> v, std::int64_t& comparisons) {
  if (std::ssize(v) < 2) return;
  const int pivot = v.back();
  std::ptrdiff_t store = 0;  // v[0, store) holds the elements less than the pivot
  for (std::ptrdiff_t i = 0; i + 1 < std::ssize(v); ++i) {
    ++comparisons;
    if (v[i] < pivot) std::swap(v[i], v[store++]);
  }
  std::swap(v[store], v.back());
  quicksort(v.first(store), comparisons);
  quicksort(v.subspan(store + 1), comparisons);
}

[[nodiscard]] std::vector<int> shuffled(int n, std::uint32_t seed) {
  std::vector<int> v(n);
  std::iota(v.begin(), v.end(), 0);
  std::mt19937 gen{seed};
  std::ranges::shuffle(v, gen);
  return v;
}

template <typename Sort>
void row(std::string_view name, Sort sort) {
  std::vector<int> random = shuffled(4096, 42);
  std::vector<int> sorted = random;
  std::ranges::sort(sorted);
  std::int64_t on_random = 0;
  std::int64_t on_sorted = 0;
  sort(random, on_random);
  sort(sorted, on_sorted);
  std::cout << std::format("{:<26}{:>9}{:>10}\n", name, on_random, on_sorted);
}

int main() {
  std::cout << std::format("{:<26}{:>9}{:>10}\n", "comparisons, n = 4096", "random", "sorted");
  row("textbook quicksort", [](std::vector<int>& v, std::int64_t& count) { quicksort(v, count); });
  row("std::ranges::sort", [](std::vector<int>& v, std::int64_t& count) {
    std::ranges::sort(v, [&count](int a, int b) {
      ++count;
      return a < b;
    });
  });
  row("std::ranges::stable_sort", [](std::vector<int>& v, std::int64_t& count) {
    std::ranges::stable_sort(v, [&count](int a, int b) {
      ++count;
      return a < b;
    });
  });
}

#include <cstdint>
#include <format>
#include <iostream>
#include <numeric>
#include <span>
#include <vector>

struct Reading {
  int robot;  // 0 <= robot < robots
  std::int64_t stamp_ms;
};

[[nodiscard]] std::vector<Reading> by_robot(std::span<const Reading> log, int robots) {
  std::vector<std::ptrdiff_t> slot(robots + 1, 0);
  for (const Reading& r : log) ++slot[r.robot + 1];         // slot[k + 1] counts robot k
  std::partial_sum(slot.begin(), slot.end(), slot.begin());  // slot[k] is where robot k starts
  std::vector<Reading> sorted(log.size());
  for (const Reading& r : log) sorted[slot[r.robot]++] = r;  // input order within a robot: stable
  return sorted;
}

int main() {
  std::vector<Reading> log;
  for (int i = 0; i < 9; ++i) log.push_back({.robot = (2 * i) % 3, .stamp_ms = 10 * i});
  for (const Reading& r : by_robot(log, 3)) std::cout << std::format("{}:{} ", r.robot, r.stamp_ms);
  std::cout << '\n';
}

