namespace detail {

// Sorts v, using buffer, whose capacity holds at least the left half of v.
template <typename T, typename Less>
void merge_sort(std::span<T> v, std::vector<T>& buffer, Less& less) {
  const std::ptrdiff_t n = std::ssize(v);
  if (n < 2) return;
  const std::ptrdiff_t mid = n / 2;
  merge_sort(v.first(mid), buffer, less);
  merge_sort(v.subspan(mid), buffer, less);
  buffer.clear();
  std::ranges::move(v.first(mid), std::back_inserter(buffer));  // the left half moves out; the right stays
  std::ptrdiff_t i = 0;    // next element of the left half, in buffer[0, mid)
  std::ptrdiff_t j = mid;  // next element of the right half, in v[mid, n)
  std::ptrdiff_t k = 0;    // next slot to fill; k <= j, so no unread element is overwritten
  while (i < mid && j < n) {
    if (less(v[j], buffer[i])) v[k++] = std::move(v[j++]);  // strictly smaller: take from the right
    else v[k++] = std::move(buffer[i++]);                   // equivalent: take from the left, stable
  }
  while (i < mid) v[k++] = std::move(buffer[i++]);  // the rest of the right half is already in place
}

}  // namespace detail

template <typename T, typename Less = std::ranges::less>
void merge_sort(std::span<T> v, Less less = {}) {
  std::vector<T> buffer;
  buffer.reserve(v.size() / 2);  // the one allocation of the whole sort
  detail::merge_sort(v, buffer, less);
}

[[nodiscard]] std::vector<int> merge_sorted(std::vector<int> v) {
  merge_sort(std::span{v});
  return v;
}

[[nodiscard]] std::vector<int> shuffled(int n, std::uint32_t seed) {
  std::vector<int> v(n);
  std::iota(v.begin(), v.end(), 0);
  std::mt19937 gen{seed};
  std::ranges::shuffle(v, gen);
  return v;
}

int main() {
  int failed = 0;
  const auto check = [&failed](std::string_view name, bool passed) {
    std::cout << std::format("{:<5}{}\n", passed ? "ok" : "FAIL", name);
    if (!passed) ++failed;
  };
  check("empty", merge_sorted({}).empty());
  check("one element", merge_sorted({5}) == std::vector{5});
  check("sorted", merge_sorted({1, 2, 3, 4}) == std::vector{1, 2, 3, 4});
  check("reversed", merge_sorted({4, 3, 2, 1}) == std::vector{1, 2, 3, 4});
  check("all equal", merge_sorted({7, 7, 7}) == std::vector{7, 7, 7});
  check("negatives and duplicates", merge_sorted({3, -1, 3, 0, -1}) == std::vector{-1, -1, 0, 3, 3});

  std::mt19937 gen{1};
  bool all_match = true;
  for (int n = 0; n <= 100; ++n) {
    std::vector<int> v(n);
    for (int& x : v) x = static_cast<int>(gen() % 10);  // values 0 to 9: many ties
    std::vector<int> expected = v;
    std::ranges::sort(expected);
    all_match = all_match && merge_sorted(v) == expected;
  }
  check("101 random inputs match std::ranges::sort", all_match);

  std::vector<std::pair<int, int>> tagged;  // (key, arrival)
  for (int i = 0; i < 40; ++i) tagged.emplace_back(i % 3, i);
  std::vector<std::pair<int, int>> expected = tagged;
  std::ranges::stable_sort(expected, {}, &std::pair<int, int>::first);
  merge_sort(std::span{tagged}, [](const auto& a, const auto& b) { return a.first < b.first; });
  check("stable: equal keys keep their arrival order", tagged == expected);

  std::vector<int> big = shuffled(4096, 42);
  std::int64_t comparisons = 0;
  merge_sort(std::span{big}, [&comparisons](int a, int b) {
    ++comparisons;
    return a < b;
  });
  check("4096 shuffled values", std::ranges::is_sorted(big));
  std::cout << std::format("{} comparisons for n = 4096\n", comparisons);
  return failed == 0 ? 0 : 1;
}

struct Detection {
  std::string label;
  int confidence_pct;     // 0 to 100
  std::int64_t range_mm;
};

#include <algorithm>
#include <compare>
#include <cstdint>
#include <format>
#include <iostream>
#include <iterator>
#include <optional>
#include <span>
#include <string>
#include <vector>

struct Detection {
  std::string label;
  int confidence_pct;  // 0 to 100
  std::int64_t range_mm;
};

void sort_for_display(std::span<Detection> detections) {
  std::ranges::sort(detections, [](const Detection& a, const Detection& b) {
    if (const auto order = a.label <=> b.label; order != 0) return order < 0;
    return a.confidence_pct > b.confidence_pct;
  });
}

[[nodiscard]] std::vector<Detection> closest(std::span<const Detection> detections, std::ptrdiff_t k) {
  std::vector<Detection> out(std::clamp(k, std::ptrdiff_t{0}, std::ssize(detections)));
  std::ranges::partial_sort_copy(detections, out, {}, &Detection::range_mm, &Detection::range_mm);
  return out;
}

[[nodiscard]] std::optional<std::int64_t> median_range(std::span<const Detection> detections) {
  if (detections.empty()) return std::nullopt;
  std::vector<std::int64_t> ranges;
  ranges.reserve(detections.size());
  std::ranges::transform(detections, std::back_inserter(ranges), &Detection::range_mm);
  const auto middle = ranges.begin() + (std::ssize(ranges) - 1) / 2;
  std::ranges::nth_element(ranges, middle);
  return *middle;
}

int main() {
  std::vector<Detection> seen{{"person", 90, 4200}, {"cone", 75, 1500},  {"person", 97, 8000},
                              {"pallet", 60, 2500}, {"cone", 88, 3100}, {"person", 70, 900}};

  for (const Detection& d : closest(seen, 2)) std::cout << std::format("{} at {} mm\n", d.label, d.range_mm);
  std::cout << std::format("closest 10 of 6: {}\n", closest(seen, 10).size());
  std::cout << std::format("median range: {} mm\n", median_range(seen).value());
  std::cout << std::format("median of none: {}\n", median_range({}).has_value());

  sort_for_display(seen);
  for (const Detection& d : seen) std::cout << std::format("{} {}% ", d.label, d.confidence_pct);
  std::cout << '\n';
}

