#include <compare>
#include <format>
#include <iostream>
#include <limits>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <tuple>
#include <vector>

// Tries every pair and triple of the sample, and names the first rule of a strict weak ordering that fails.
template <typename T, typename Less>
[[nodiscard]] std::optional<std::string_view> broken_rule(std::span<const T> sample, Less less) {
  const auto equivalent = [&](const T& a, const T& b) { return !less(a, b) && !less(b, a); };
  for (const T& a : sample) {
    if (less(a, a)) return "irreflexivity";
    for (const T& b : sample) {
      if (less(a, b) && less(b, a)) return "asymmetry";
      for (const T& c : sample) {
        if (less(a, b) && less(b, c) && !less(a, c)) return "transitivity";
        if (equivalent(a, b) && equivalent(b, c) && !equivalent(a, c)) return "transitivity of equivalence";
      }
    }
  }
  return std::nullopt;
}

struct Cell {
  int x;
  int y;
};

void report(std::string_view comparison, std::optional<std::string_view> rule) {
  std::cout << std::format("{:<32}{}\n", comparison, rule ? "breaks " + std::string(*rule) : "no rule broken");
}

int main() {
  const std::vector<int> ints{1, 2, 2, 3};
  const std::vector<Cell> cells{{0, 1}, {1, 0}, {1, 1}};
  const std::vector<double> doubles{1.0, std::numeric_limits<double>::quiet_NaN(), 2.0};

  report("a <= b", broken_rule<int>(ints, [](int a, int b) { return a <= b; }));
  report("a.x < b.x || a.y < b.y", broken_rule<Cell>(cells, [](const Cell& a, const Cell& b) {
           return a.x < b.x || a.y < b.y;
         }));
  report("a < b, with a NaN", broken_rule<double>(doubles, [](double a, double b) { return a < b; }));
  report("a < b", broken_rule<int>(ints, [](int a, int b) { return a < b; }));
  report("std::tie(a.x, a.y) < ...", broken_rule<Cell>(cells, [](const Cell& a, const Cell& b) {
           return std::tie(a.x, a.y) < std::tie(b.x, b.y);
         }));
  report("std::strong_order(a, b) < 0", broken_rule<double>(doubles, [](double a, double b) {
           return std::strong_order(a, b) < 0;
         }));
}
